inline const Entry* Find(std::string_view code){for(const auto& entry:All)if(entry.Code==code)return &entry;return nullptr;}
inline const Entry& Get(Id id){return All[static_cast<std::size_t>(id)];}
inline constexpr std::string_view Reference="https://gh0sted5456-us.github.io/RuneSchema/ERROR-CODES/";
inline std::string Url(const Entry& entry){return std::string(Reference)+"#"+std::string(entry.Anchor);}
inline std::string_view Category(std::string_view code,bool structured=false){
    if(!structured)if(const auto* entry=Find(code))return entry->Subsystem;
    const auto family=code.substr(0,code.rfind('-'));
    if(family=="RS-ASSET")return "Assets";
    if(family=="RS-BLD")return "Buildings";
    if(family=="RS-BP")return "Blueprints";
    if(family=="RS-CORE")return "Runtime";
    if(family=="RS-CRS")return "Courses";
    if(family=="RS-ENUM")return "Enums";
    if(family=="RS-EQP")return "Equipment";
    if(family=="RS-GE")return "Gameplay effects";
    if(family=="RS-IMP")return "Imports";
    if(family=="RS-JSON")return "Configuration and definitions";
    if(family=="RS-LOAD")return "Loaders";
    if(family=="RS-NIA")return "Niagara";
    if(family=="RS-NPC")return "NPCs";
    if(family=="RS-RAW")return "Data tables";
    if(family=="RS-REC")return "Recipes";
    if(family=="RS-RGST")return "Registry";
    if(family=="RS-SPAWN")return "Spawns";
    if(family=="RS-STR")return "Strings";
    if(family=="RS-VND")return "Vendors";
    if(family=="RS-JRN")return "Journal";
    return "Other diagnostics";
}
